questionvariables.text:
/* Use predefined tuples representing [A, B, C] to ensure clean integer intercepts */
/* Expanded to 16 variants to allow for more deployments */
tuples : [
    [1, 2, 8], [2, 3, 12], [3, 4, 12], [2, 1, 8], [3, 2, 12], [4, 3, 12],
    [1, 3, 9], [3, 1, 9], [1, 2, 10], [2, 1, 10], [1, 4, 12], [4, 1, 12],
    [2, 5, 10], [5, 2, 10], [3, 2, 6], [2, 3, 6]
];
tup : rand(tuples);
A : tup[1];
B : tup[2];
C : tup[3];

y_int : C / B;
x_int : C / A;
m : -A / B;

/* Base expression for the worked solution */
line_expr : m*x + y_int;

/* Define target answers */
ta1 : y_int;
ta2 : x_int;

/* The line is strictly dashed, and shaded below. */
ta3 : A*x + B*y < C;
